from socket import socket, AF_INET, SOCK_STREAM
from taf.hw.rf_switch.devices.rf_switch import RfSwitch
from taf.hw.rf_switch.exceptions import RfSwitchActionFailed, RfSwitchActionNotSupported


class RFSM665270(RfSwitch):
    SUPPORTED_PORT_IN_VALUES = [str(value) for value in range(1, 66)]
    SUPPORTED_PORT_OUT_VALUES = [str(value) for value in range(1, 3)]
    """
    Module to control HBTE types based RF switches.
    """
    def __init__(self, ip, port=3000):
        super().__init__()
        self.ip = ip
        self.port = int(port)
        self.client_socket = socket(AF_INET, SOCK_STREAM)
        self.client_socket.settimeout(30.0)
        self.client_socket.connect((self.ip, self.port))

    def connect_ports(self, port_in, port_out):
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        recv = self._execute_command('Query:About?')
        if "RFSM-6-65-2-70" in recv:
            self._operate_ports(port_in, port_out)
        else:
            msg = "Expected model: HBTE-RFSM-6-65-2-70 not found in device response"
            raise RfSwitchActionFailed(msg)

    def disconnect_ports(self, port_in, port_out='1'):
        msg = "Action not supported for this device."
        raise RfSwitchActionNotSupported(msg)

    def get_port_in_status(self, port_in):
        if port_in not in self.SUPPORTED_PORT_IN_VALUES:
            error_msg = f'Given port_in: {port_in} is not supported.'
            raise RfSwitchActionFailed(error_msg)
        query_command = 'Query:Status?'
        _, port_out, status = self._execute_and_parse_query(query_command)
        if status == "OFF":
            return None
        else:
            return port_out

    def get_port_out_status(self, port_out):
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        query_command = 'Query:Status?'
        port_in, _, _ = self._execute_and_parse_query(query_command)
        return port_in

    def get_connected_ports(self):
        query_command = 'Query:Status?'
        port_in, port_out, _ = self._execute_and_parse_query(query_command)
        return {port_in: port_out}

    def _operate_ports(self, port_in, port_out):
        enable_command = f"Set:ON:A{port_in}-{port_out}"
        recv = self._execute_command(enable_command)
        if 'Succeed' not in recv:
            raise RfSwitchActionFailed(f'Enable in_port:{port_in} out_port:{port_out} error.')

    def _execute_command(self, command):
        command += "\r\n"
        command = command.encode()
        self.client_socket.send(command)
        recv = self._receive()
        if len(recv) == 0:
            raise RfSwitchActionFailed("Received empty response from the device.")
        return recv

    def _execute_and_parse_query(self, query):
        recv = self._execute_command(query)
        return self._parse_query_response(recv)

    def _receive(self):
        response = self.client_socket.recv(1024)
        response = response.replace(b'\x00', b'')
        return response.decode()

    @staticmethod
    def _parse_query_response(response):
        # response example: "Status:A1-2:ON"  and "Status:None"
        if "None" in response:
            return None, None, None
        else:
            flag, port_in_out, status = response.split(":")
            port_in, port_out = port_in_out.split("-")
            return port_in, port_out, status
